--
-- Table structure for table `song`
--

DROP TABLE IF EXISTS `song`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `song` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '歌曲名',
  `artist` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '歌手',
  `album` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '专辑',
  `genre` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流派',
  `duration` int DEFAULT '0' COMMENT '时长（秒）',
  `original_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上传时的原始文件名',
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '落盘文件名（UUID）',
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '相对存储路径',
  `file_size` bigint NOT NULL COMMENT '文件大小（字节）',
  `file_md5` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件 MD5（用于去重/秒传）',
  `mime_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MIME 类型',
  `ext` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扩展名（小写）',
  `cover_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面相对路径',
  `lyric_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '歌词文件（LRC）相对路径',
  `uploader_id` bigint NOT NULL COMMENT '上传者 ID（仅管理员上传，不可为空）',
  `download_count` int NOT NULL DEFAULT '0' COMMENT '下载次数',
  `play_count` int NOT NULL DEFAULT '0' COMMENT '播放次数',
  `like_count` int NOT NULL DEFAULT '0' COMMENT '喜欢数',
  `comment_count` int NOT NULL DEFAULT '0' COMMENT '评论数',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1-正常（上架） 0-下架',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `netease_id` bigint DEFAULT NULL COMMENT '网易云歌曲ID（导入歌词/封面的来源锚点）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_md5` (`file_md5`),
  UNIQUE KEY `uk_song_netease_id` (`netease_id`),
  KEY `idx_title` (`title`),
  KEY `idx_uploader` (`uploader_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=227 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='歌曲表';
/*!40101 SET character_set_client = @saved_cs_client */;

