--
-- Table structure for table `song_comment`
--

DROP TABLE IF EXISTS `song_comment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `song_comment` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `song_id` bigint NOT NULL COMMENT '歌曲 ID',
  `user_id` bigint NOT NULL COMMENT '评论人 ID',
  `parent_id` bigint DEFAULT NULL COMMENT '父评论 ID（NULL=根评论，回复统一指向根评论）',
  `reply_user_id` bigint DEFAULT NULL COMMENT '被回复用户 ID（楼中楼"回复@xx"）',
  `content` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容（含 [表情名] 占位符）',
  `image_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配图相对路径（单图，可为 GIF）',
  `like_count` int NOT NULL DEFAULT '0' COMMENT '点赞数（冗余，点赞时维护）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除（删根评论=整楼隐藏）',
  PRIMARY KEY (`id`),
  KEY `idx_song_time` (`song_id`,`create_time`),
  KEY `idx_parent` (`parent_id`),
  KEY `idx_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='歌曲评论表';
/*!40101 SET character_set_client = @saved_cs_client */;

